import{_ as t,c as n,o as s,j as a,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"易纂言卷十二","description":"易纂言 - 易纂言卷十二","frontmatter":{"title":"易纂言卷十二","description":"易纂言 - 易纂言卷十二"},"headers":[],"relativePath":"classics/zuanyan/013.md","filePath":"classics/zuanyan/013.md"}'),r={name:"classics/zuanyan/013.md"};function c(o,e,i,p,d,u){return s(),n("div",null,[...e[0]||(e[0]=[a("h1",{id:"易纂言卷十二",tabindex:"-1"},[l("易纂言卷十二 "),a("a",{class:"header-anchor",href:"#易纂言卷十二","aria-label":"Permalink to “易纂言卷十二”"},"​")],-1),a("p",null,"欽定四庫全書",-1),a("p",null,"元吳澄撰",-1),a("p",null,"雜卦傳 雜者，錯糅其次，不依文王卦序也。序卦上經三十卦，下經三十四卦。以反對而觀，則上經十八卦，下經十八卦也。此篇仍其反對之偶，而不仍其先後之序，故曰「雜」。其義則以明六十四卦所主之爻也。",-1),a("p",null,"「乾」剛坤柔，「比」樂師憂，「臨」「觀」之義，或與或求。 六十四卦，乾坤為純剛純柔之卦。剛柔之畫自初起，至上而極，然後見「乾」為純剛，上「坤」為純柔，故「乾」主上九，「坤」主上六。「乾」「坤」，六陽六陰之卦，為主；「夬」「剝」，五陽五陰之卦，五為主；「大壯」「觀」，四陽四陰之卦，四為主；泰「否」，三陽三陰之卦，三為主；「臨」「遁」，二陽二陰之卦，二為主；復「姤」，一陽一陰之卦，初為主。此十二卦主爻，與術家世爻同。「比」九五居上，為顯比之主，故「樂」。「師」九二居下，為行師之主，故「憂」。「與」者，上與下。求者，下求上。「臨」九二，二陽浸長，在上之陰不敢以勢臨之而與之，以俟其上進。「觀」六四，四陰已盛，然不進逼犯陽，而統率三陰居下，以求觀九五之中正。此一節六卦，四句一韻。 屯見而不失其居，蒙雜而著。「震」，起也；「艮」，止也。「損」、「益」，盛衰之始也。 屯、蒙，皆二陽之卦。屯九五見於上卦二陰之中而為主，其下一陽則動於坎險之內而固守，故曰「不失其居」。「蒙」九二雜於下卦二陰之中而為主，其上一陽則止於坎險之外而光明，故曰「著坎」。陽陷於陰中，一也。見者，陽在上卦之天而位顯。雜者，陽在下卦之地而位幽也。「震」九四起而在上卦之下。「艮」上九止而在上卦之上。「損」自泰變，泰三往上，損其下也。泰變而損，為衰之始。「益」自否變，否四來初，益其下也。否變而益，為盛之始。或以損之後必益為盛之始，益之後必損為衰之始，非也。此一節六卦，五句二韻。 大畜，時也。無妄，災也。萃聚而升不來也，謙輕而豫怠也。 「大畜」以「大壯」之四往上為主，二陰尊而上之，得其時也。「無妄」以遁之三來初為主，九不處三，而三受失中之災也。「萃」以觀之四往上為主，而同類之三陰聚於下。升以臨之三來初為主，而同類之三陰升於上。升上為往，降下為來。不來，謂升而不降也。謙一陽居下卦之上，為謙卑之主，而不尊大，故自小而輕。「豫」一陽居上卦之下，為豫樂之主，而志滿足，故自肆而怠。此一節六卦，四句一韻。 噬嗑，食也。「賁」，無色也。兌見而巽伏也。「隨」，無故也。「蠱」則飭也。 食者，物在口中，必噬而合之。無色者，質而不文，必賁而飭之。否，上下不交，不能噬齧而食也。「噬嗑」以否初往五而為主，否五遂得來初，成頤口之象，而可噬嗑以食。泰上下皆純卦，無間雜之色成文也。賁以泰上來二文剛而為主，泰二遂得往上文柔，而賁其無色之質。兌上六，一陰說而見於二陽之上。巽六四，一陰入而伏於二陽之下。隨初九為主，聽二陰自隨，而無所作為。蠱初六，為生承乾，父體壞而有所整治。無故者，無所事也。飭者，韻有所事也。此一節六卦，五句一 剝，爛也。復，反也。晉，晝也。明夷，誅也。井通而困相遇也。 剝六五，消陽將盡，僅存一陽，陽剛壞爛之極也。復初九，當純坤之後，一陽生於下，陽剛來反之初也。晉六五，離日當天，晝也。明夷六二，離日入地。明者，夷傷也。誅，即夷傷之義。升九五，自初升五，坎水上通而將出井口。困九二，自上降二，與二陰相遇而揜其前後。此一節六卦，五句二韻。 鹹，速也。恆，久也。渙，離也。節，止也。解，緩也。蹇，難也。 鹹九三，不上感正應而下感，近比，欲速感也。恆初六，以柔巽處卑下，妻道之可久者也。渙九二，坎水在巽風之下，為風所離散。節九五，坎水在兌澤之上，為澤所節止。解九二，坎陷在內，震則出險而動於外，內險已解緩也。蹇九五，坎險在外，艮則見險而止於內，外險方艱難也。此一節六卦，六句，二韻。 睽，外也。家人，內也。否、泰，反其類也。大壯則止，遁則退也。 睽六五在外為主，家人六二在內為主。否三四相易為「漸」，泰三四相易為歸妹。漸四復反於三，就其同類之陰，則為「否」；歸妹四復反於三，就其同類之陽，則為泰，故曰「反其類也」。大壯四陽進而消陰，遁二陰進而消陽。慮後陽之恃其壯，故不欲九四之進，而欲其止；慮前陽之不及遁，故不欲六二之進，而欲其退也。聖人於五陽之夬，亦不欲陽之輕進；於一陰之姤，亦惟欲陰之不往，蓋同此意也。此一節六卦，五句，一韻。 大有，眾也。同人，親也。革，去故也。鼎，取新也。小過，過也。中孚，信也。 大有六五，以一陰有五陽，所有眾也。同人六二以中正同，中正，其情親也。革六二離火在內，而兌澤燥涸，蓋尾閭焦釜之火，去其澤水之故者也。鼎六五離火在上，而巽木生之，蓋燧改薪傳之火，取其木火之新者也。小過九四主也，而為六五所過，蓋陰盛能過，陽衰不及也。中孚六四主也，而為九五所信，蓋陽實能感，陰虛能應也。此一節六卦六句一韻。 豐，多故也；親寡，旅也。離上而坎下也。小畜，寡也。履，不處也。 篇內三「故」字三義。隨無故，事故之故也。革去故，新故之故也。豐多故，親故之故也。豐六二在內，為主於明盛之中，外與四相易，而情相得，初亦往尚，三亦來孚，故舊之多也。旅六五在外，為主於羈窮之中，內與三相易，而情不相親，相親者寡也。蓋豐盛則故舊合，旅窮則親戚離，人情然也。離六五為主，火炎而上，故上徵而折上九之首。坎九五為主，水潤而下，故下比而納六四之約。小畜，一陰畜藏於五陽之間，所畜者甚寡少也。履六三履行於二陽之上，所履者剛，又不得正位，非其所安，故行去而不留處也。此一節六卦五句一韻。 需，不進也；訟，不親也。大過，顛也。頤，養正也。既濟，定也。未濟，男之窮也。歸妹，女之終也。漸，女歸待男行也。姤，遇也，柔遇剛也。夬，決也，剛決柔也，君子道長，小人道憂也。 需九五為主，而下三陽「需」待於內，不上進乎五也。訟九二為主，而上三陽違行於外，不下親乎二也。萃聚，升不來，需不進，訟不親，皆言三陰三陽之於卦主，為同類而不相與也。大過上六為主，而下應九三，猶首之向下而顛也。頤上九為主，而下養五四，以上之養下為正也。既濟六二主也，以陰居陰，得其定位，而上下五爻亦皆得其定位，故曰定也。未濟九二主也，以陽居陰，失其正位，而同類二陽亦皆失其正位，故曰男之窮也。三陰亦不得正位，不足言也。歸妹六三，為女君之娣，而歸於男家。女之少者，既歸則歸，女之事終也。漸九三，得男位之正，而將往迎女，六四之女待其親迎而後行也。姤初六，一陰始生於下，而遇九二之剛，有浸長消陽之勢。夬九五，五陽將極於上，而夬去上六之陰。陽剛，君子之道息而將極，故曰長；陰柔，小人之道消而將盡，故曰憂也。此一節十卦十四句五韻。先生著是書幾四十年，其間稿成改易者凡數四。壬戌秋書成，然未嘗以示人。明年春，觀生固請鋟諸梓以惠學者。先生幸慨然許之，猶慮傳寫之或差，乃命抄寫而自督視，因正其未安，明其句讀，而益加詳密。寫未及半，適特旨遣使召入翰林，度不可辭，不數日上道。觀生隨侍至郡城，集同志分帙畢寫。將及九江，點校才竟，若卦圖象例，陸續刊行。因書之成，遂志年月於右方雲。然嘗聞諸先生曰：「吾於易書用功至久，下語尤精，其象例皆自得於心，亦庶乎文王、周公繋辭之意。」又曰：「吾於書有功於世，視易為猶小，吾於易有功於世為甚大。」則讀是書者，其可不知先生用意深切而泛視之哉！",-1),a("p",null,"至治癸亥五月五日，觀生謹志。 易纂言卷十二。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
